let api = app.grouped("api")
let protected = api
    .grouped(User.authenticator())             // delegated mechanism
    .grouped(User.guardMiddleware())           // checkpoint after authenticator
protected.get("orders") { req in
    let user = try req.auth.require(User.self) // request-scoped principal
    return try await orders(for: user, on: req.db)
}
